// Module Web Worker: the route search and the circuit solves, off the page's thread, so the map and the panel stay
// usable while a big corridor or box is worked out.
//
// The worker keeps its own copy of the road graph (sent once per graph, not per solve), the wasm solver, the last
// selection and, with it, the route search's setup (best-route.mjs keeps that with the selection), so a re-route for
// another detour limit or turn-cost scale starts at once. A solve runs to the end without reading messages: to stop
// one, the page ends the worker and starts another, which gets the graph again.
//
// Protocol:
//   in:  { type: 'init', wasm }                 URL of dist/solver.wasm
//        { type: 'graph', graph }               the typed graph (CONTRACT.md section 2); replaces the last one
//        { id, type: 'solve', mode: 'pair' | 'omni', route | box, bufM, params, via, radiusM, current, best, prefs,
//          noteF? }                             select the corridor (route, bufM) or the box, then the circuit solve
//                                               (model.mjs run) if `current`, then the best route (best-route.mjs,
//                                               options `prefs`) if `best`
//        { id, type: 'route', params, via, prefs, noteF? }    the best route again on the last selection
//        params.noteF (road notes, one factor per atom) is not sent with params: `noteF` (an array, or null) comes
//        only when it has changed, and the worker keeps it
//   out: { id, type: 'selected', n }            junctions in the selection (a solve only), before the work starts
//        { id, type: 'done', n, m, chains, global, result, best, ms }   n junctions, m roads; chains (with `current`)
//                                               and global: the selection's chain and node numbers in the graph;
//                                               result: what run returned, or null; best: the route, { error } or null
//        { id, type: 'stale' }                  'route' with no selection (a new worker): send a 'solve'
//        { id, type: 'error', message }
import { loadSolver, selectCorridor, selectBox, run } from './model.mjs';
import { lowestResistanceRoute } from './best-route.mjs';

let solver = null, graph = null, sel = null, selKey = null, noteF = null;
self.onmessage = async (ev) => {
  const m = ev.data;
  if (m.type === 'init') { solver = loadSolver(m.wasm); return; }
  if (m.type === 'graph') { graph = m.graph; sel = null; selKey = null; noteF = null; return; }
  try {
    const t0 = performance.now();
    if (m.noteF !== undefined) noteF = m.noteF;
    const params = { ...m.params, noteF };
    if (m.type === 'solve') {
      const key = JSON.stringify([m.box ?? m.route, m.bufM]);
      if (key !== selKey) { sel = m.box ? selectBox(graph, m.box) : selectCorridor(graph, m.route, m.bufM); selKey = key; }
      self.postMessage({ id: m.id, type: 'selected', n: sel.x.length });
    } else if (!sel) { self.postMessage({ id: m.id, type: 'stale' }); return; }
    if (m.spin) { const end = performance.now() + m.spin; while (performance.now() < end); } // test hook (smoke-solve.mjs): a solve that takes this long
    const t1 = performance.now();
    let result = null, best = null;
    if (m.type === 'solve' && m.current && sel.chains.length) result = run(await solver, graph, sel, { mode: m.mode, radiusM: m.radiusM, params, via: m.via });
    const t2 = performance.now();
    if (m.best && sel.chains.length) { try { best = lowestResistanceRoute(graph, sel, params, { via: m.via, ...m.prefs }); } catch (e) { console.error(e); best = { error: e.message }; } }
    const t3 = performance.now();
    const chains = result ? Int32Array.from(sel.chains) : null, global = m.type === 'solve' ? Int32Array.from(sel.global) : null;
    self.postMessage({ id: m.id, type: 'done', n: sel.x.length, m: sel.chains.length, chains, global, result, best,
      ms: { select: t1 - t0, current: t2 - t1, route: t3 - t2, total: t3 - t0 } },
    [chains, global, result?.cur, result?.flow, result?.norm].filter(Boolean).map((a) => a.buffer));
  } catch (e) {
    self.postMessage({ id: m.id, type: 'error', message: e?.message ?? String(e) });
  }
};
